// Page headlines ("Word <em>word</em>") are translated as a whole.
const LEADS = {
  'Scrim reports': 'Laporan <em>scrim</em>',
  'What do we train today?': 'Apa yang kita <em>latih hari ini</em>?', 'Road to Juara Umum': 'Menuju <em>Juara Umum</em>', 'Weekly brief': 'Ringkasan <em>mingguan</em>',
  'Competitor analysis': 'Analisis <em>kompetitor</em>', 'Tournament week': 'Pekan <em>turnamen</em>', 'Between games': 'Antar <em>game</em>', 'Athlete readiness': 'Kesiapan <em>atlet</em>',
  'Player plans': 'Rencana <em>pemain</em>', 'Coaching cycle': 'Siklus <em>coaching</em>', 'Is the hub helping?': 'Apakah hub <em>membantu</em>?',
};
const norm = (s) => s.replace(/\s+/g, ' ').trim();
export function tr(text) {
  const s = norm(text); if (!s) return null;
  if (Object.prototype.hasOwnProperty.call(EXACT, s)) return EXACT[s];
  for (const [p, t] of PREFIX) if (s.startsWith(p)) return t;
  for (const [re, rep] of RULES) if (re.test(s)) return s.replace(re, rep);
  return null;
}

// Translate a rendered subtree in place.
export function translateDom(root, lang) {
  if (lang !== 'id') return;
  const doc = root.ownerDocument || root;
  for (const el of root.querySelectorAll('.lead')) { const k = norm(el.textContent); if (LEADS[k]) { el.innerHTML = LEADS[k]; el.setAttribute('data-no-tr', ''); } }
  for (const o of root.querySelectorAll('option:not([value])')) o.setAttribute('value', o.textContent);
  const walk = doc.createTreeWalker(root, 4); const nodes = []; let n;
  while ((n = walk.nextNode())) { const p = n.parentElement; if (!p || p.closest('script,style,textarea,[data-no-tr]')) continue; nodes.push(n); }
  for (const node of nodes) {
    const v = node.nodeValue; const t = tr(v); if (t == null) continue;
    const lead = v.match(/^\s*/)[0], trail = v.match(/\s*$/)[0]; node.nodeValue = lead + t + trail;
  }
  for (const el of root.querySelectorAll('[placeholder],[aria-label],[title]')) for (const a of ['placeholder', 'aria-label', 'title']) { const v = el.getAttribute(a); if (v) { const t = tr(v); if (t != null) el.setAttribute(a, t); } }
}
